const DATA={
 raina:{title:'末班车以后还有别的路',friend:'雨音把私人路线的一角给你看，手指停在一个没有雨声的地方：“下次我想先选这里。不是让你一直等我，是我也想学着邀请。”朋友的位置没有被写成等候恋爱的站台。',sugar:'雨音先说了想见你的时间，又认真划掉一个自己承担不了的晚上。“以前我觉得说不行会让位置不见，现在想试着把真的愿意说清楚。”她没有再用每晚都在证明喜欢。',after:'雨音提起一条你们以前没走过的路。她先确认这次只是按现在说好的朋友范围分享，不借旧站台暗示复合。你们可以记得过去，也不必重演过去。',choices:['把这张路线暂时收好，今晚只听她讲发现','各留一个现在想去的地方，不急着排成同一条路'],results:['雨音讲完了第一次自己拐弯的经过。路线卡收进私人记录，没有被当作新的见面承诺。','你的目的地与雨音的不一样。两个地点并排写着，没有谁为了留在同一站把自己的擦掉。']},
 ash:{title:'欢迎牌也有背面',friend:'阿澈把一张新路线发过来，写的不是集合公告，而是“我想去玩”。他讲自己怎么在休息与欢迎新人之间重新排时间，也认真问你最近有没有想只为自己做的事。',sugar:'阿澈再次说清自己珍惜的是友谊；这一页不会用旅程将近结束逼他改变答案。',after:'阿澈把欢迎牌翻过去，按已经确认的联系范围问了一句近况。他没有借大家都在场要求你恢复过去的亲密。',choices:['只选一个自己也想参加的小玩法','各讲一个没有对观众开放的收藏'],results:['这次你们没有准备欢迎词，只交换了想尝试的玩法。阿澈不再负责保证每个人开心，自己也成了愿意来玩的那一个。','你们没有交换整份收藏夹，只说一件愿意分享的小事。未公开的部分也有稳稳的位置。']},
 mika:{title:'标题不再替谁作答',friend:'小满把这一轮的纪念页翻开，空白处没有擅自写下砂糖。她想听你会怎样给一段重要友谊起名，也愿意保留彼此不同的答案。',sugar:'小满把你们已经确认的称呼写在一张单独的纸上，又把具体日历放在旁边。“名字和答应做的事，我想都认真记着。”她不要求每一页都有合照，也不把一次失落判成整段关系失败。',after:'小满把旧标题留在旧页，新页按现在的联系范围另起。她没有删掉共同经历，也先问你是否愿意在这次新记录里出现。保存不代表复合，缺席也不等于否认过去。',choices:['分别写一个属于自己的标题，不公开彼此的版本','只记录这次谈话里双方愿意留下的一句话'],results:['你们各自写好标题，仍然允许另一份不交出来。共同经历没有因为两种命名就变成了争夺正确答案。','一人选了一句话，先确认另一方愿意被记住的范围。纪念页没有补出照片，也没有自动对外公开。']},
 rei:{title:'两个时钟上的空格',friend:'零点没有给你一张排满的日程表，而是讲起一个独自解决的问题。他问你最近是否也有想留给自己完成的事。错开的几晚终于不再只是等候的空白。',sugar:'零点把还没验证的工程关掉，先问你这晚真正想讲什么。“我们可以继续喜欢，也不必替对方接下所有工程。”他已经想好下次怎样提前说明忙碌，具体见面仍要双方确认。',after:'零点先说明这次按已经谈好的朋友方式联系，不再沿用旧的固定时段。工程也各自保存，分享一段进展不附带重新靠近的义务。',choices:['互讲一个独自做过的判断，先不交换工程','只分享能异步读完的一小段说明'],results:['两个问题都被认真听完，没有谁接走另一个人的全部任务。结束谈话时，各自的生活仍在继续。','你们各留下一段短说明，没发完整工程，也没要求今晚读完。异步联系有了可以停下的地方。']},
 lin:{title:'最后一首可以不播放',friend:'凛说自己收藏了一首还没想好给谁听的歌。这回她没打开播放器，而是问你最近最想听哪种声音。她可以喜欢热闹，也可以决定把最后一首留给自己。',sugar:'凛把演出邀请和两人时间放在不同的栏里。“我不想你永远当观众，也不想我们只有我没演出的空档。”她认真听你的安排，没让任何一方先交出整份生活。',after:'凛先问你愿不愿意按现在的朋友范围聊一会儿，没有把同一支舞当作和好的暗号。舞台与私人相处都换了新入口，旧称呼不再被起哄喊出来。',choices:['今晚不放歌，互讲一件舞台外的日常','各留一首只写名字的歌，什么时候听由自己决定'],results:['这一段谈话没有背景音乐，凛仍然讲到了自己想留下的一个瞬间。散场时没有谁被要求把气氛再抬高。','两首歌的名字并排收好，风格一点也不相同。你们没有用播放次数比较在意程度。']},
 yuki:{title:'制作名单之外的名字',friend:'弥生把作品清单与朋友名单分开来。“有的东西还没做完，但认识你不是等它发布才成立。”她想问你这轮真正记得哪一步，也愿意听一个不够漂亮的答案。',sugar:'弥生先把两人各自做过的部分标清，再关掉工程：“今晚想和你相处，不是继续请你修报错。”合作与喜欢都是真的，也需要允许彼此偶尔只来聊天。',after:'弥生保留了过去合作的署名，新工程却先按现在的联系范围另开。她没有把保留署名当作复合的承诺，也没有要求你通过删稿证明放下。',choices:['各说一处愿意保留的试错，不急着发布','把尚未完成的部分列清，今晚停在这里'],results:['你们各挑了一处真实的试错。未完成的工程仍未完成，已经发生过的支持也没有因此失效。','清单保留了能确认和还做不到的部分。弥生保存文件，今晚没有再用重做整夜证明认真。']},
};
export const FINALES=PEOPLE.map(p=>({id:'finale-'+p.id,npc:p.id}));
export function finaleReady(run,q){const r=run.relationships[q.npc],d=run.departures['player:'+q.npc];return FINALES.some(s=>s.id===q.id&&s.npc===q.npc)&&!q.other&&run.day>=24&&r?.introduced&&r.stage===2&&run.day>=(run.storyFlags[`read:arc:${q.npc}:1`]||run.day)+2&&!run.storySeen.includes(q.id)&&!departureContactReason(run,q.npc)&&!r.intent?.state?.includes('waiting')&&d?.resolution!=='active'&&(r.status!=='salt'||d?.contact==='friends'&&d.aftermath?.length===2);}
export function finaleMessages(run){return FINALES.filter(q=>finaleReady(run,q)).map(q=>({type:'scene',...q,optional:true}));}
export function finaleScene(run,q){const d=DATA[q.npc];if(!d)return null;const r=run.relationships[q.npc],route=r.status==='salt'?2:r.status==='sugar'?1:0;return {npc:q.npc,title:d.title,subtitle:'人物阶段小结 · '+PEOPLE.find(p=>p.id===q.npc).name,text:d[['friend','sugar','after'][route]]+(r.status==='sugar'&&r.tension>35?'\n\n你们仍有尚未解决的压力。今晚只确认眼下能说清的部分，不用一个温柔收尾盖掉旧的问题。':''),choices:d.choices.map((label,i)=>({label,text:d.results[i],effects:i===0?{social:1,energy:-2}:{balance:2,mood:-1},rel:{trust:2},outcome:'finale-read',finaleRoute:route}))};}
export function characterEnding(run,npc){const entry=run.storybook.findLast(x=>x.id==='finale-'+npc);if(!entry)return null;const route=run.storyFlags['finale-route:'+npc];if(![0,1,2].includes(route))return null;return {key:[npc,route,entry.choice].join(':'),npc,route,choice:entry.choice,title:entry.title+' · '+['把这一刻留下','给以后留一段空白'][entry.choice]};}
export function validCharacterEndings(l){return Array.isArray(l.characterEndings)&&l.characterEndings.length<=36&&new Set(l.characterEndings).size===l.characterEndings.length&&l.characterEndings.every(k=>typeof k==='string'&&/^[a-z]+:[012]:[01]$/.test(k)&&PEOPLE.some(p=>p.id===k.split(':')[0]));}
